import{U as m,u,k as d,aR as p,J as y,aS as f,g as h,P as b,aP as w,aT as v}from"./SF2abpFc.js";function I(s=!1){const t=m,e=t.l.u;if(!e)return;let n=()=>b(t.s);if(s){let a=0,o={};const g=w(()=>{let c=!1;const r=t.s;for(const i in r)r[i]!==o[i]&&(o[i]=r[i],c=!0);return c&&a++,a});n=()=>h(g)}e.b.length&&u(()=>{l(t,n),p(e.b)}),d(()=>{const a=y(()=>e.m.map(f));return()=>{for(const o of a)typeof o=="function"&&o()}}),e.a.length&&d(()=>{l(t,n),p(e.a)})}function l(s,t){if(s.l.s)for(const e of s.l.s)h(e);t()}v();const k=1,A={name:"Andrea Lissak",wordmark:"andrea",role:"Software Engineer",tagline:"I build web and mobile apps, backends, and projects involving computer vision and hardware.",quote:"I like working with people on small, useful tools that stay useful. Paid cloud infrastructure isn’t always necessary and there are often overlooked ways to run an app at zero cost. Where I can, I build for the browser and use free services for storage, keeping maintenance low so projects can survive beyond the initial enthusiasm.",projectHandover:"If you ask me to build a project, you own the finished product and I hand it over once the work is done. If you need changes or fixes later, you can come back to me. I’m not currently taking on ongoing project management.",pageTitle:"Andrea Lissak — Software Engineer",description:"Apps, web tools and smaller experiments I’ve built, plus my work at Yahoo. Projects cover web, mobile, backends, computer vision and hardware.",featuredHeading:"Featured projects",workHeading:"Work",archiveHeading:"More projects",contactHeading:"Send a message",contactCopy:"You can message me here without an account. Leave your email or messaging handle so I can get back to you.",messageLabel:"Your message",messagePlaceholder:"What do you have in mind? Leave a way for me to get back to you.",sendLabel:"Send message",sentMessage:"Thanks, your message was sent.",emailIntro:"Or email me at",email:"andrea.media.info@gmail.com",githubUrl:"https://github.com/yissok",accessSentMessage:"Thanks, your request was sent.",detailHeading:"What it does",notesHeading:"Implementation notes",missingHeading:"Nothing here",missingCopy:"This page doesn’t exist.",noScriptIntro:"You’ll need JavaScript for the project previews. You can also find my work on"},S=[{id:"penguin-steps",name:"Penguin Steps",category:"iOS · Walking with a partner",kind:"app",color:"#c9ddd8",accent:"#356d62",image:"projects/penguin-steps/images/penguin-steps-main-screen.jpg",media:[{type:"image",src:"projects/penguin-steps/images/penguin-steps-main-screen.jpg",alt:"Penguin Steps main screen",poster:""},{type:"image",src:"projects/penguin-steps/images/penguin-steps-screen-02.jpg",alt:"Penguin Steps second screen",poster:""}],description:"Compare daily steps with a partner using Apple Health. Each of you has a penguin that moves as you walk, so you can see who’s ahead.",tags:["Apple Health","Swift","Firebase"],note:"You pair up and track steps in the iOS app.",links:[["App Store","https://apps.apple.com/gb/app/penguin-steps/id6762652426"]],private:!0},{id:"dropleet",name:"Dropleet",category:"Web · Java interview practice",kind:"web",color:"#e8d6cc",accent:"#a44b32",image:"projects/dropleet/images/dropleet-main-screen.jpg",media:[{type:"image",src:"projects/dropleet/images/dropleet-main-screen.jpg",alt:"Dropleet main screen",poster:""},{type:"image",src:"projects/dropleet/images/dropleet-screen-02.png",alt:"Dropleet second screen",poster:""},{type:"image",src:"projects/dropleet/images/dropleet-screen-03.png",alt:"Dropleet third screen",poster:""}],description:"LeetCode problems broken into smaller questions, so you can work through the reasoning behind a solution. An LLM generates question sets from JSON you supply, and Google Forms collects the answers. The site is static, so you can share it without needing an account or running a backend.",tags:["Java","Algorithms","LLM-generated"],note:"",links:[["Visit site","https://dropleet.co.uk/"]],private:!0},{id:"reacter",name:"Reacter",category:"iOS · Reaction game",kind:"app",color:"#e5d0cc",accent:"#a63d3d",image:"projects/reacter/images/reacter-main-screen.jpg",media:[{type:"image",src:"projects/reacter/images/reacter-main-screen.jpg",alt:"Reacter interface preview",poster:""},{type:"video",src:"projects/reacter/videos/reacter-demo.mp4",alt:"Reacter demo",poster:"projects/reacter/posters/reacter-demo-poster.png",original:"https://yissok.github.io/HQ_videos/reacter.mp4"}],description:"A reaction game for iPhone and iPad where you tap targets as quickly as you can. I first released it in 2015.",tags:["Native iOS","Swift"],note:"",links:[["App Store","https://apps.apple.com/gb/app/reacter/id993435226"]]},{id:"pixelbot",name:"Pixelbot",category:"iOS + macOS · Pixel monitoring",kind:"app",color:"#d5d7e7",accent:"#545b8e",image:"projects/pixelbot/images/pixelbot-iphone-screen.jpg",media:[{type:"video",src:"projects/pixelbot/videos/pixelbot-demo.mp4",alt:"Pixelbot demo",poster:""},{type:"image",src:"projects/pixelbot/images/pixelbot-iphone-screen.jpg",alt:"Pixelbot iPhone app",poster:""},{type:"image",src:"projects/pixelbot/images/pixelbot-mac-dashboard.jpg",alt:"Pixelbot Mac dashboard",poster:""}],description:"If you’re waiting for something on your Mac, pick a pixel that will change when it’s done. Pixelbot watches it and notifies your phone, so you don’t have to keep checking the screen.",tags:["macOS app","iOS app","No account"],note:"The Mac app watches the pixel and the iOS app receives the notification. You don’t need an account.",links:[["App Store","https://apps.apple.com/gb/app/pixelbot/id1560553386"],["Mac App Store","https://apps.apple.com/gb/app/pixelbot-dashboard/id1560523831?mt=12"]],private:!0},{id:"cell",name:"Cell Counter",category:"Web · Cell counting",kind:"web",color:"#ddd5e3",accent:"#76518b",image:"projects/cell/images/cell-cover.jpg",media:[{type:"image",src:"projects/cell/images/cell-screen-01.png",alt:"Cell Counter main screen",poster:""},{type:"image",src:"projects/cell/images/cell-screen-02.png",alt:"Cell Counter second screen",poster:""},{type:"image",src:"projects/cell/images/cell-screen-03.png",alt:"Cell Counter third screen",poster:""},{type:"image",src:"projects/cell/images/cell-screen-04.png",alt:"Cell Counter fourth screen",poster:""}],description:"Count cells from a photo of a microscope screen, then calculate seeding density, well counts and media volumes in the same tool. You don’t need an account.",tags:["Computer vision","Image processing","No account"],note:"",links:[["Visit site","https://scout-38aa2.web.app/cell"]],private:!0},{id:"latent-semantic-analysis",name:"Latent Semantic Analysis",category:"Web · Keyword mind maps",kind:"web",color:"#d7dfca",accent:"#657948",image:"shared/project-placeholder.svg",media:[{type:"video",src:"projects/latent-semantic-analysis/videos/latent-semantic-analysis-demo.mp4",alt:"Latent Semantic Analysis demo",poster:"projects/latent-semantic-analysis/posters/latent-semantic-analysis-demo-poster.png",original:"https://yissok.github.io/HQ_videos/yoogle.mp4"},{type:"image",src:"projects/latent-semantic-analysis/images/latent-semantic-analysis-screenshot-02.png",alt:"",poster:""},{type:"image",src:"projects/latent-semantic-analysis/images/latent-semantic-analysis-screenshot-03.png",alt:"",poster:""}],description:"Give it some keywords and it uses Google search signals to estimate how closely each pair is related, then shows the results as a weighted graph.",tags:["JS","SQL","PHP"],note:"",links:[["View repository","https://github.com/yissok/Blending-Google-and-the-old-Yahoo"]],placeholder:!0},{id:"gym-app",name:"Gym Crowdedness",category:"Arduino · Hardware + backend",kind:"web",color:"#e5dfca",accent:"#827034",image:"shared/project-placeholder.svg",media:[{type:"image",src:"projects/gym-app/images/gym-app-screenshot-01.png",alt:"",poster:""},{type:"image",src:"projects/gym-app/images/gym-app-screenshot-02.png",alt:"",poster:""},{type:"video",src:"projects/gym-app/videos/gym-app-demo.mp4",alt:"Gym Crowdedness demo",poster:"projects/gym-app/posters/gym-app-demo-poster.png",original:"https://yissok.github.io/HQ_videos/fitin.mp4"},{type:"image",src:"projects/gym-app/images/gym-app-screenshot-04.png",alt:"",poster:""}],description:"Arduino sensors count people entering and leaving a gym, then send the count to a backend over HTTP so you can see how busy it is.",tags:["Arduino","Hardware","Backend"],note:"",links:[["View repository","https://github.com/yissok/Gym-App"]],placeholder:!0},{id:"family",name:"Family Tree",category:"Web · Family tree editor",kind:"web",color:"#d8dec8",accent:"#62743c",image:"projects/family/images/family-illustration.svg",media:[{type:"image",src:"projects/family/images/family-main-screen.png",alt:"Family Tree main screen",poster:""},{type:"image",src:"projects/family/images/family-screen-02.png",alt:"Family Tree second screen",poster:""}],description:"A family tree you can explore as a graph and edit as text. You can import or export the tree, and you don’t need an account.",tags:["Interactive editor","Text import/export","No account"],note:"",links:[["Visit site","https://scout-38aa2.web.app/family/"]],private:!0}],T=[{id:"map",name:"Map",category:"Web · Routes & journey timing",description:"A map experiment where you can save routes, time journeys and compare your position with a virtual pace setter.",private:!0,missing:!1,hosted:!0,links:[["Visit site","https://scout-38aa2.web.app/map"]]},{id:"university-projects",name:"University projects",category:"Archive · CS coursework",description:"My university projects, including computer vision, population simulations, timetable optimisation, 3D graphics and games.",private:!1,missing:!1,hosted:!0,links:[["Explore archive","https://yissok.github.io/"]]},{id:"block-cipher-aes-128-apps",name:"Block Cipher AES-128 apps",category:"Swift · Encryption",description:"System shortcuts for encrypting and decrypting text on your device using AES-128.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/your-encrypter"]]},{id:"picture-encrypter",name:"Picture encrypter",category:"Swift · Image processing",description:"Encrypts pictures with AES-128, turning them into images that look like static.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/encrypture"]]},{id:"kubernetes-full-stack",name:"Kubernetes full-stack",category:"React · Java · Kubernetes",description:"A template for running a Java backend and React frontend with Kubernetes. You access the app through the server IP.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/kube"]]},{id:"cost-saving-personal-backend",name:"Cost-saving personal backend",category:"AWS · Node · MongoDB",description:"A personal backend using API Gateway, MongoDB and Node.js authentication on EC2, with CloudFront serving the static frontend. CloudFormation and GitHub Actions handle the infrastructure and deployment.",private:!1,missing:!1,hosted:!0,links:[["Backend","https://github.com/yissok/backend"],["Static frontend","https://github.com/yissok/static-frontend"],["Node bastion","https://github.com/yissok/node-bastion"]]},{id:"serverless-chat",name:"Serverless Chat",category:"Swift · Peer-to-peer",description:"A chat app that uses a disposable Firebase credential embedded in the app to wrap the APNS key used for notifications, so it can run for free without a dedicated chat server.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/no-strings"]]},{id:"zero-operating-cost-contractor-site-tap-in",name:"Zero operating cost Contractor site tap in",category:"Google Apps Script",description:"A contractor tap-in site that uses Google Sheets as its database and a static interface, with no operating cost.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/site"]]},{id:"coffee-chatbot",name:"Coffee chatbot",category:"Python",description:"A bot for coordinating coffee deliveries through Symphony chat. I built it, but it’s no longer hosted and the source isn’t available here.",private:!1,missing:!0,hosted:!0,links:[]},{id:"knowledge-share-chatbot",name:"Knowledge-share chatbot",category:"Node.js · MySQL",description:"A chatbot that passes questions to people who might know the answer.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/nomuraLifehacks"]]},{id:"structured-notes",name:"Structured Notes",category:"Notes",description:"Take a note through an iOS shortcut and its first word decides where it goes. You can encrypt notes locally before saving them to a GitHub repository.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Structured-Notes"]]},{id:"peer-to-peer-chat",name:"Peer to Peer Chat",category:"P2P chat",description:"A browser chat experiment using WebRTC to send messages to several peers. A small Node.js server sets up the connections.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Peer-to-Peer-Chat"]]},{id:"light-pong",name:"Light Pong",category:"Game",description:"Two-player Pong on an Arduino. An LED acts as the ball, each player has a button, and a servo and melodies tell you how the game is going.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Light-Pong"]]},{id:"physics-playground",name:"Physics Playground",category:"Physics sandbox",description:"A 2D physics sandbox using dyn4j. You can try different forces and constraints and watch bodies fall, collide and stack.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Physics-Playground"]]},{id:"recursive-text-adventure",name:"Recursive Text Adventure",category:"Text game",description:"A Haskell text adventure played in the terminal. Each command passes the updated game state into the next recursive call.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Recursive-Text-Adventure"]]},{id:"arduino-tic-tac-toe",name:"Arduino Tic Tac Toe",category:"Arduino · Game",description:"Two Arduinos send moves to each other using LED flashes and light sensors, so you can play tic tac toe over light.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Arduino-Tic-Tac-Toe"]]},{id:"corner-detector",name:"Corner Detector",category:"Computer vision",description:"Python experiments with image convolution, matching objects at different scales and rotations, and SIFT feature detection.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Corner-Detector"]]},{id:"3d-playground",name:"3D Playground",category:"3D graphics",description:"A C++ and OpenGL project for loading 3D models, moving around them and switching between vertices, edges and shaded faces.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/3D-Playground"]]},{id:"asp-timetabling",name:"Answer Set Programming for timetabling",category:"ASP · Timetabling",description:"Generates university timetables from room, lecturer and student constraints, then ranks them by preferences. You can browse the results in a Java GUI.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Answer-Set-Programming-for-timetabling"]]},{id:"dungeon-of-doom",name:"Dungeon Of Doom",category:"Game",description:"A multiplayer dungeon game where players and bots compete for gold and try to reach an exit. You can make your own maps.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Dungeon-Of-Doom"]]},{id:"population-behaviours",name:"Population Behaviours",category:"Simulation",description:"A NetLogo model of cooperation. Agents cooperate or defect, and their interactions produce spatial patterns you can watch in the simulation.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Population-Behaviours"]]},{id:"intensity-template-matching",name:"Intensity Based Template Matching",category:"Computer vision",description:"Finds a template in a larger image by sliding it across the image and comparing pixel intensities. Written in Python using NumPy, SciPy and OpenCV.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Intensity-Based-Template-Matching"]]},{id:"snake",name:"Snake",category:"Game · 2010",description:"A small version of Snake I wrote in Pascal in 2010.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Snake"]]},{id:"new-1ff6d9c7",name:"Image Classifier",category:"MATLAB · Computer vision",description:"A MATLAB classifier for six types of binary shapes. It uses boundary chain codes, Fourier features and Gaussian models, then checks the predictions with confusion matrices.",private:!0,missing:!1,hosted:!1,links:[["View repository","https://github.com/yissok/machine-learning-classifier"]]}],j=[{id:"yahoo",employer:"Yahoo",role:"Software Engineer",period:"Nov 2020 – Apr 2026",metric:"750+ PRs across 60+ repositories",stack:"Java 17 · Spring Boot 3 · Hibernate/JPA · MySQL · Liquibase/Flyway · AWS Lambda/CloudFormation/S3/EMR/Glue/Redshift · Kafka · Docker/Rancher · Chef · JUnit · Cucumber · JaCoCo · GitHub Enterprise · Screwdriver CI/CD · GitHub Actions",areas:[{id:"creative-platform",title:"Creative Management Platform",lede:"I was the lead maintainer of an internal Java GWT platform for about 3.5 years. Around 100 people used it, and I then led development of its replacement in Spring Boot 3 and Java 17.",body:"I designed and built the replacement service, including the REST API, RSQL list filters, Hibernate/JPA persistence and AOP audit logging. I also added Google Sheets access through a service account, OpenAPI documentation and the CI/CD pipeline.",tags:"Java · Spring Boot · Hibernate/JPA · RSQL",items:[{title:"AWS operations",text:"The API runs on ECS Fargate, with Prometheus collecting Micrometer and Spring Boot Actuator metrics. I built an analytics viewer for the business, and CloudWatch alarms reach whoever is on call through Opsgenie. I also found that an auto-update bot was provisioning more resources than needed, so I cut that back to reduce the cost."}]},{id:"legacy-migration",title:"Legacy Platform Migration",lede:"I drove a migration away from the legacy ad-serving stack over several months.",body:"Changes often affected several repositories at once, so I coordinated the application, database, ETL and Lambda changes across the main GWT repo, its db migration repo, its downstream reporting migration repo, AWS Glue jobs and AWS Lambda functions.",tags:"AWS Glue · AWS Lambda",items:[]},{id:"revenue-attribution",title:"Revenue Attribution",lede:"I built a system that uses metadata to trace advertising revenue back to the internal creative team that made the original asset.",body:"The parent API server was too slow to check metadata on each request, so I designed a solution to extract the attribution data through the UI instead. Once I deployed it, the revenue team could query the database directly.",tags:"Java · Metadata pipelines",items:[]},{id:"data-platform",title:"Data Platform & Infrastructure",lede:"I was responsible for substantial parts of the data pipeline.",body:"That included Redshift schemas and views, Glue ETL, Kafka event collection, EMR job orchestration and Lambda monitoring.",tags:"Redshift · Glue · Kafka · EMR · Lambda",items:[]},{id:"ad-ops-api",title:"Ad Operations API",lede:"From 2024, I was the lead backend contact for projects across four squads working on a company-wide ad-operations API.",body:"The API serves around 400 active users across all time zones. I landed roughly 250 PRs over about 18 months. Find description of that work in the next paragraphs.",tags:"Java · Spring Boot · Hibernate/JPA · MySQL",items:[{title:"Multiple KPIs",text:"I was one of the 2 backend engineers that carried out the bulk of the work for turning a field that used to host a single enum value into a field that would accommodate a collection of enum values. While the change was simple, it revealed hidden, unexpected complexities management and seniors failed to predict. Specifically, any place in the codebase that checked for that field had to be converted into a check on the new collection replacing that field. This would be fine to do in most cases, however, being the field vital for monetisation and pacing of campaigns, it required hundreds of case-specific refactoring edits across our validation infrastructure. My role was just completing that work and communicating the progress with the project manager so they could report on timelines of delivery to upper management."},{title:"Target Completion Rate",text:"I added additional field to the domain model, validators, audit log and import/export, then rolled it out in two phases behind a feature gate."},{title:"Goal type",text:"I added ROAS support for Audio and CTV and replaced existing reporting calculations with new ones provided by science team."},{title:"AdLearn2 enforcement migration",text:"I tightened POST and PUT validation, added status reporting and wrote a migration cron job to update existing data and state."},{title:"RAG AI assistant integration",text:"I added OAuth and CKMS support for a third-party RAG assistant, covering authentication, secret rotation and key sanitisation."}]},{id:"ai-tooling",title:"AI Tooling",lede:"I built a Claude Code skill called “where is my Jira ticket” to work out which ticket a change belongs to.",body:"",tags:"Claude Code · Jira API",items:[{title:"Environment awareness",text:"The skill checks the branch and deployment status, then sends a sub-agent to query the Jira API. That lets it find the ticket linked to a change and report its current state and location."}]}]},{id:"nomura",employer:"Nomura",role:"Platform Engineering",period:"",metric:"",stack:"",areas:[{id:"mobile-framework",title:"Mobile Development Framework",lede:"I built a shared framework and wizard for creating work-profile apps. Each app starts with the same security and branding defaults, so teams don’t have to set these up separately.",body:"",tags:"Mobile · Platform Engineering",items:[{title:"Approvals in one place",text:"Each new app goes through one auditable process for security, branding, legal and engineering-management approvals."}]}]}],P=JSON.parse(`[{"id":"peer-to-peer-chat","name":"Peer to Peer Chat","repoUrl":"https://github.com/yissok/Peer-to-Peer-Chat","tagline":"A browser chat experiment using WebRTC to send messages to several peers.","how":["Browser pages exchange messages over <strong>WebRTC data channels</strong>. Each page shows its own ID, the other peers and any messages it receives.","A small Node.js server helps the browsers find each other. When a page connects over WebSocket, it gets a numeric ID and a peer list, then the server forwards the offers, answers and network candidates needed to connect.","If you choose <em>Send message to ALL</em>, the client goes through the peer list and opens a connection to each recipient, skipping itself. Messages go directly between browsers once the server has helped set up the connection.","I extended a caller-and-callee example with peer IDs, discovery and the option to send to several recipients. The original demo runs across browser pages connected to a local signalling server."],"media":[{"type":"video","src":"projects/peer-to-peer-chat/videos/peer-to-peer-chat-demo.mp4","alt":"","poster":"projects/peer-to-peer-chat/posters/peer-to-peer-chat-demo-poster.png","original":"https://yissok.github.io/HQ_videos/ptp.mp4"}],"smart":["The Node.js server uses <code>ws</code> on port <code>8090</code>, and the browser connects to <code>ws://localhost:8090/</code>.","Connection messages are JSON objects containing offers, answers, ICE candidates or peer IDs. The server forwards them to the recipient with the sender’s ID.","Each connection uses <code>RTCPeerConnection</code> and a data channel called <code>communication</code>. The sender creates the channel before generating the offer.","The peer list is stored in <code>localStorage</code>. A recursive function visits each recipient and waits <code>100 ms</code> before sending, rather than checking the channel’s open event.","This is a prototype. There’s no server cleanup when a peer disconnects, and sending only works if the connection is ready within that fixed delay."],"links":[]},{"id":"reacter","name":"Reacter","repoUrl":"https://github.com/yissok/iOS-Game","tagline":"A reaction game for iPhone and iPad that I first released in 2015.","how":["Reacter is about <strong>reaction speed</strong>. Tap each target as quickly and accurately as you can to improve your score.","I first released it on the App Store in 2015, using the Xcode tools available then. Much of that tooling is now deprecated, so the code also serves as a record of an early iOS project."],"media":[{"type":"video","src":"projects/reacter/videos/reacter-demo.mp4","alt":"","poster":"projects/reacter/posters/reacter-demo-poster.png","original":"https://yissok.github.io/HQ_videos/reacter.mp4"}],"smart":["First released on the App Store in 2015.","The game uses one screen and timed taps.","The source still reflects the iOS tools I used at the time."],"links":[["App Store","https://apps.apple.com/gb/app/reacter/id993435226"]]},{"id":"light-pong","name":"Light Pong","repoUrl":"https://github.com/yissok/Light-Pong","tagline":"Two-player Pong on an Arduino, using LEDs as the ball.","how":["I built <strong>Pong</strong> with six LEDs and an Arduino. The light moves between two players, each with a button at their end.","Press when the light reaches your side and you score a point. If you press at the wrong time, the other player gets the point.","A servo shows who’s ahead and by how much. A piezo element plays different melodies for the start and end of the game, and when someone scores or misses.","You can turn a potentiometer to change the delay between LEDs from about 150 ms to 50 ms. When the game ends, all the LEDs light up, a melody plays and the winner’s side keeps blinking."],"media":[{"type":"video","src":"projects/light-pong/videos/light-pong-demo.mp4","alt":"","poster":"projects/light-pong/posters/light-pong-demo-poster.png","original":"https://yissok.github.io/HQ_videos/pong.mp4"},{"type":"image","src":"projects/light-pong/images/light-pong-screenshot-02.png","alt":"","poster":""}],"smart":["Six LEDs show the moving ball and score feedback.","Each player’s button connects to an interrupt pin, so presses can be detected during the game.","The servo shows the score difference on a scale from <code>-5</code> to <code>+5</code>. Either end means a lead of at least five points.","The potentiometer changes the delay between LEDs from roughly 150 ms down to 50 ms.","The piezo plays different sounds when the game starts or ends, or a player scores or misses.","I put straws around the LEDs to spread the light along each cylinder and help hide the wiring.","At the end, all LEDs light up, a melody plays and the winner’s LEDs blink repeatedly."],"links":[]},{"id":"physics-playground","name":"Physics Playground","repoUrl":"https://github.com/yissok/Physics-Playground","tagline":"A sandbox for trying things out with 2D physics.","how":["A <strong>2D rigid-body physics</strong> sandbox using William Bittle’s dyn4j engine.","You can change forces and constraints and see what happens as bodies fall, collide, stack and settle."],"media":[{"type":"video","src":"projects/physics-playground/videos/physics-playground-demo.mp4","alt":"","poster":"projects/physics-playground/posters/physics-playground-demo-poster.png","original":"https://yissok.github.io/HQ_videos/physics.mp4"}],"smart":["dyn4j handles collision detection and rigid-body simulation.","You can experiment with shapes, joints and forces.","It runs as an executable JAR."],"links":[]},{"id":"recursive-text-adventure","name":"Recursive Text Adventure","repoUrl":"https://github.com/yissok/Recursive-Text-Adventure","tagline":"A Haskell text adventure that passes the game state through recursive calls.","how":["A text adventure written in <strong>Haskell</strong> and played in the terminal. Each command passes the updated state into another recursive call, so changes are modelled with pure functions rather than a shared mutable world object.","The whole game is in <code>functionalGame.hs</code>. Compile it with GHC, then play in the terminal."],"media":[{"type":"video","src":"projects/recursive-text-adventure/videos/recursive-text-adventure-demo.mp4","alt":"","poster":"projects/recursive-text-adventure/posters/recursive-text-adventure-demo-poster.png","original":"https://yissok.github.io/HQ_videos/haskell.mp4"}],"smart":["Each recursive call receives the game state.","The game is one Haskell file, compiled with GHC."],"links":[]},{"id":"gym-app","name":"Gym Crowdedness","repoUrl":"https://github.com/yissok/Gym-App","tagline":"Counts people at the gym and uses past occupancy to suggest when to go.","how":["Fit In started with a practical question: <strong>how busy is the gym, and when should I go?</strong> Research with students and Sports Training Village staff pointed to overcrowding at the university gym and the lack of useful occupancy information.","Two laser sensors count people entering and leaving. The order in which someone crosses the beams tells the counter whether to add or subtract a person. It uploads the count every five minutes and resets it at 3am.","The website shows the current count, past occupancy and predictions based on that history. If you create an account and add your timetable, it can compare your free periods with the gym data and suggest a time to visit.","The Android app loads the mobile website in a JavaScript-enabled <code>WebView</code>, so changes to the site reach the app without publishing another APK."],"media":[{"type":"video","src":"projects/gym-app/videos/gym-app-demo.mp4","alt":"","poster":"projects/gym-app/posters/gym-app-demo-poster.png","original":"https://yissok.github.io/HQ_videos/fitin.mp4"}],"smart":["Two laser sensors connect to the Arduino. The order in which their beams break tells it whether someone is entering or leaving.","The counter uploads occupancy every five minutes and resets its local count to zero at 3am.","The site uses <code>HTML</code>, <code>CSS</code>, <code>JavaScript</code> and <code>PHP</code>.","The prediction system uses stored occupancy data to find patterns and estimate future counts.","If you add your timetable, the site can suggest quieter periods when you’re actually free.","Accounts support registration, login and password changes using PHP sessions. JavaScript checks inputs first, then PHP validates them on the server, with jQuery <code>AJAX</code> sending the data.","The Android <code>WebView</code> has JavaScript enabled and needs an internet connection.","The prototype used two boards. Possible next steps were to combine them into one embedded system, shrink the enclosure, add permanent mounting and power, and improve connectivity."],"links":[]},{"id":"arduino-tic-tac-toe","name":"Arduino Tic Tac Toe","repoUrl":"https://github.com/yissok/Arduino-Tic-Tac-Toe","tagline":"Two Arduinos send tic tac toe moves to each other using flashes of light.","how":["The idea was to see whether two computers could exchange useful data without wires, Wi-Fi or Bluetooth. Two Arduinos communicate through <strong>light</strong>, with an LED sending data and a light-dependent resistor on the other board receiving it.","Each player enters a square number in the serial monitor to play noughts and crosses. Their board updates locally, then sends that number to the other Arduino.","The sender turns the move into a custom binary-like code and flashes it through the LED. The receiver reads the flashes, works out the square number and updates the other player’s board.","The programs take turns sending and receiving, with one player going first. That’s enough to keep both boards up to date using only changes in light."],"media":[{"type":"video","src":"projects/arduino-tic-tac-toe/videos/arduino-tic-tac-toe-demo.mp4","alt":"","poster":"projects/arduino-tic-tac-toe/posters/arduino-tic-tac-toe-demo-poster.png","original":"https://yissok.github.io/HQ_videos/tictactoe.mp4"},{"type":"image","src":"projects/arduino-tic-tac-toe/images/arduino-tic-tac-toe-screenshot-02.png","alt":"","poster":""}],"smart":["Each Arduino has an <strong>LED to send data</strong> and a light-dependent resistor to receive it. The LED sits close to the other board’s sensor.","Squares are numbered 1 to 9, left to right and top to bottom, then encoded as four binary-like digits.","The custom encoding sends the least significant digit first.","A 100 ms flash marks the start of a message, followed by 100 ms for each encoded digit.","Testing showed that the sensors could sample slightly faster than every 50 ms. The receiver reads the middle 50 ms of each 100 ms interval, so it’s less likely to catch a transition.","A move can be sent and read in under half a second.","I tested the boards inside a box with a lid to keep changes in outside light from interfering."],"links":[]},{"id":"corner-detector","name":"Corner Detector","repoUrl":"https://github.com/yissok/Corner-Detector","tagline":"Python experiments with convolution, template matching and SIFT features.","how":["I used Python to try several <strong>computer vision</strong> techniques: convolution, intensity-based object matching and a SIFT feature-detection pipeline. OpenCV, NumPy and SciPy handle image and numerical operations.","The convolution function pads greyscale images so their dimensions stay the same. I tested Gaussian blur, sharpening, horizontal edge detection and identity kernels, then compared the results with SciPy.","For object recognition, the training step makes templates at different scales and rotations. Testing slides each template across an image and scores the correlation. If the best match for a class passes the threshold, it draws a labelled box at that scale and rotation.","The <strong>SIFT</strong> implementation looks for interest points across Difference-of-Gaussians pyramids, filters out low-contrast points and edges, then assigns magnitudes and orientations to the remaining keypoints. Orientation histograms describe the area around each point."],"media":[{"type":"video","src":"projects/corner-detector/videos/corner-detector-demo.mp4","alt":"","poster":"projects/corner-detector/posters/corner-detector-demo-poster.png","original":"https://yissok.github.io/HQ_videos/corner.mp4"}],"smart":["Written in Python using <code>OpenCV</code>, <code>NumPy</code>, <code>SciPy</code> and <code>Matplotlib</code>.","The convolution function pads the image and flips the kernel before applying it. I checked it against <code>scipy.ndimage.convolve</code>.","Template matching uses RGB data so it keeps the colour information.","Training creates templates at 50%, 25%, 12.5% and 6.25% scale, with twelve rotations from 0° to 330° in 30° steps.","Templates are saved as binary <code>.dat</code> files using <code>pickle</code>, so testing can load them faster.","OpenCV’s <code>matchTemplate</code> scores normalised correlation. I chose a <code>0.5</code> threshold through testing before drawing detections.","SIFT uses three octaves and Difference of Gaussians. It compares each candidate with 26 neighbours in space and scale, then uses Hessian-based filtering to reject edge responses.","Each keypoint has 16 orientation histograms with eight buckets each, giving a 128-value descriptor."],"links":[]},{"id":"3d-playground","name":"3D Playground","repoUrl":"https://github.com/yissok/3D-Playground","tagline":"A C++ and OpenGL project for loading 3D models and moving around them.","how":["A C++ project where I experimented with <strong>interactive 3D rendering</strong> in <code>OpenGL</code>.","It loads <code>.obj</code> models, including the Stanford bunny and a screwdriver, and scales and positions them in the scene. You can switch between <em>vertices</em>, <em>edges</em> and shaded faces.","The camera turns with the mouse and moves relative to where you’re looking. If you switch to grounded movement, you get horizontal movement, gravity and jumping.","The renderer supports lighting, materials and smooth shading from calculated vertex normals. It also maps BMP textures onto a cube."],"media":[{"type":"video","src":"projects/3d-playground/videos/3d-playground-demo.mp4","alt":"","poster":"projects/3d-playground/posters/3d-playground-demo-poster.png","original":"https://yissok.github.io/HQ_videos/bunny.mp4"},{"type":"image","src":"projects/3d-playground/images/3d-playground-screenshot-02.png","alt":"","poster":""}],"smart":["The <code>.obj</code> loader reads vertices and faces and records which faces touch each vertex.","Face normals come from <strong>cross products</strong>. Angle-weighted vertex normals give the models smooth shading.","Model bounds determine how to scale and position an imported mesh.","The camera uses yaw and pitch for rotation and <code>gluLookAt</code> to set the view.","Vector normalisation and cross products give the camera-relative movement directions.","You can render <em>vertices</em>, <em>edges</em> or <em>faces</em>.","The renderer uses <code>OpenGL</code> lighting, materials, depth testing and smooth shading.","It supports BMP textures and a separate movement mode with gravity and jumping."],"links":[]},{"id":"asp-timetabling","name":"Answer Set Programming for timetabling","repoUrl":"https://github.com/yissok/Answer-Set-Programming-for-timetabling","tagline":"A constraint solver that generates university timetables and ranks them by preferences.","how":["The project uses <strong>Answer Set Programming</strong> to make university timetables from students, units, lecturers, rooms, time slots and other commitments. <code>clingo</code> finds schedules that satisfy the rules.","The model generates possible lecture and student assignments, then rules out combinations that break the constraints. Weak constraints rank the valid schedules by preferences, so a timetable can be valid but still less desirable than another.","You can read the <code>clingo</code> output directly or send its JSON to <code>ASPinterpreter.java</code> and browse the timetable in a Java GUI. There are separate basic, extended and edge-case test inputs.","I tested how input size affects runtime. More time slots and lecture hours caused the largest increases, because they give the solver many more possible arrangements to check."],"media":[{"type":"video","src":"projects/asp-timetabling/videos/asp-timetabling-demo.mp4","alt":"","poster":"projects/asp-timetabling/posters/asp-timetabling-demo-poster.png","original":"https://yissok.github.io/HQ_videos/asp.mp4"}],"smart":["The timetable rules are written in <strong>Answer Set Programming</strong> and run with <code>clingo</code>.","The ASP files use <code>.pl</code> for syntax highlighting in the IDE.","<code>ASPinterpreter.java</code> reads the JSON output with <code>json-simple-1.1.jar</code> and shows it in a GUI.","Generators and constraints produce valid schedules. Weak constraints rank them by preferences.","The attendance generator includes <code>takes(S,U)</code>, so it skips impossible student/unit pairs instead of generating them and filtering them later.","The model can group clusters of lecture preferences.","I used <code>basic</code>, <code>ext</code> and <code>edge</code> test sets with different inputs to check correctness and runtime.","The search space grows quickly as time slots and lecture hours increase. For <code>n</code> slots and <code>k</code> hours, the arrangement count analysed was <code>n!/(n-k)!</code>."],"links":[]},{"id":"dungeon-of-doom","name":"Dungeon Of Doom","repoUrl":"https://github.com/yissok/Dungeon-Of-Doom","tagline":"A multiplayer dungeon game where players and bots compete for gold.","how":["A <strong>multiplayer dungeon game</strong> with a server and separate clients. Start the server with the default map or a custom one made from floor, wall, gold and exit tiles.","Players connect through <code>PlayGame</code>, collect gold and try to reach an exit. The map file sets how much gold you need, so different maps can have different winning conditions.","Several players can compete for the same gold, and two players can’t stand on the same tile. That makes where you move part of the competition.","If you don’t have other players, you can start bots through <code>BotLauncher</code>. They join the same map and follow the same movement rules."],"media":[{"type":"video","src":"projects/dungeon-of-doom/videos/dungeon-of-doom-demo.mp4","alt":"","poster":"projects/dungeon-of-doom/posters/dungeon-of-doom-demo-poster.png","original":"https://yissok.github.io/HQ_videos/dod.mp4"}],"smart":["<code>Server</code> hosts the game, <code>PlayGame</code> connects a player and <code>BotLauncher</code> starts bots.","Custom maps are text files in <code>maps</code>, using <code>.</code>, <code>#</code>, <code>G</code> and <code>E</code> for tiles.","The server keeps the earlier text version’s protocol, apart from <code>LOOK</code> changes needed for multiple clients.","The GUI uses the same communication structure as the earlier text interface.","Each tile is an 8×8 grid of small panels. Updating its rows and columns progressively gives the appearance of movement.","The GUI uses <code>GridBagLayout</code> and can be resized.","The server allows up to 20 clients. Disconnected clients don’t free up reusable slots in this version.","The client’s quit action disconnects from the server cleanly. Closing the GUI window is a separate action."],"links":[]},{"id":"population-behaviours","name":"Population Behaviours","repoUrl":"https://github.com/yissok/Population-Behaviours","tagline":"A NetLogo model of how cooperation evolves in harsh environments.","how":["A NetLogo model looking at <strong>how cooperation evolves</strong>. Agents cooperate or defect, using dynamics from Smaldino, Schank and McElreath (2013), and Smaldino (2013).","You can load it in NetLogo Web and watch the interactions produce spatial patterns. The individual rules let you see how the cost of cooperation affects the result."],"media":[{"type":"video","src":"projects/population-behaviours/videos/population-behaviours-demo.mp4","alt":"","poster":"projects/population-behaviours/posters/population-behaviours-demo-poster.png","original":"https://yissok.github.io/HQ_videos/swarm.mp4"}],"smart":["The rules come from published cooperation models from 2013.","Spatial patterns emerge as the agents interact.","You can run the model in NetLogo Web."],"links":[]},{"id":"intensity-template-matching","name":"Intensity Based Template Matching","repoUrl":"https://github.com/yissok/Intensity-Based-Template-Matching","tagline":"Finds a template in a larger image by comparing pixel intensities.","how":["A Python project that slides a template across a larger image and compares <strong>pixel intensities</strong> to find the closest match.","The main script runs it against test images using SciPy, NumPy and OpenCV. The modules follow the same structure as the Corner Detector project."],"media":[{"type":"video","src":"projects/intensity-template-matching/videos/intensity-template-matching-demo.mp4","alt":"","poster":"projects/intensity-template-matching/posters/intensity-template-matching-demo-poster.png","original":"https://yissok.github.io/HQ_videos/waldo.mp4"}],"smart":["A sliding window checks the template at different positions.","Configuration, convolution and matching have separate modules.","Pixel intensities determine the match score."],"links":[]},{"id":"snake","name":"Snake","repoUrl":"https://github.com/yissok/Snake","tagline":"A small version of Snake I wrote in Pascal in 2010.","how":["I wrote this in Pascal in <strong>2010</strong>. It’s Snake: move around the grid, collect food and avoid the walls and your own tail.","I’ve kept it as part of my earlier work. The whole game is in <code>snake.pas</code>."],"media":[{"type":"video","src":"projects/snake/videos/snake-demo.mp4","alt":"","poster":"projects/snake/posters/snake-demo-poster.png","original":"https://yissok.github.io/HQ_videos/snake.mp4"}],"smart":["Written in Pascal in 2010.","snake.pas contains the input handling, movement, collision checks and drawing."],"links":[]},{"id":"serverless-chat","name":"Serverless chat","repoUrl":"https://github.com/yissok/Serverless-Chat","tagline":"An iOS experiment with peer-to-peer chat and push notifications.","how":["A two-person chat app written in Swift, using <strong>peer-to-peer networking</strong> to send messages directly between devices without a dedicated chat server.","I also tried a Firebase and APNS setup for push notifications, with a disposable Firebase credential embedded in the app."],"media":[],"smart":["Messages travel between peers.","Push notifications use Firebase and APNS.","The app contains a disposable Firebase credential."],"links":[["View repository","https://github.com/yissok/Serverless-Chat"]]},{"id":"structured-notes","name":"Structured notes","repoUrl":"https://github.com/yissok/Structured-Notes","tagline":"Take a note through an iOS shortcut and its first word decides where it goes. You can encrypt notes locally before saving them to a GitHub repository.","how":["An iOS Shortcut setup that <strong>organises notes by their first word</strong>. Write <em>groceries: milk</em> and it goes under groceries, or <em>idea: deck</em> and it goes under idea.","A second shortcut creates keys. If you want to encrypt notes under a particular key, that happens locally before another shortcut saves the map to GitHub.","To read a note, query the repository by keyword. Plaintext comes straight from the map, while encrypted notes open in the app through an app URL."],"media":[{"type":"video","src":"projects/structured-notes/videos/structured-notes-demo.mp4","alt":"","poster":"projects/structured-notes/posters/structured-notes-demo-poster.png","original":"https://yissok.github.io/HQ_videos/snotes.mp4"}],"smart":["The first word determines the note’s key.","Shortcuts create keys and save notes to GitHub.","Selected notes are encrypted locally and read back in the app."],"links":[["View repository","https://github.com/yissok/Structured-Notes"]]},{"id":"latent-semantic-analysis","name":"Latent Semantic Analysis","repoUrl":"https://github.com/yissok/Blending-Google-and-the-old-Yahoo","tagline":"Estimates how closely keywords relate using Google searches and an old Yahoo directory.","how":["An experiment in <strong>how closely keywords are related</strong>. Give it a set of terms and it scores each pair, then draws the results as a weighted graph.","The score combines Google search signals with the old, human-curated Yahoo directory, so it has two different sources to judge the relationship.","A PHP backend calculates and stores the counts, and a canvas interface draws the graph."],"media":[{"type":"video","src":"projects/latent-semantic-analysis/videos/latent-semantic-analysis-demo.mp4","alt":"","poster":"projects/latent-semantic-analysis/posters/latent-semantic-analysis-demo-poster.png","original":"https://yissok.github.io/HQ_videos/yoogle.mp4"}],"smart":["The score uses search co-occurrence and Yahoo directory relationships.","Each pair’s score becomes a weight in the graph.","The PHP backend saves counts so it can reuse them."],"links":[]},{"id":"new-1ff6d9c7","name":"Image Classifier","repoUrl":"https://github.com/yissok/machine-learning-classifier","tagline":"A MATLAB classifier that identifies binary shapes from their boundaries.","how":["A MATLAB <strong>image classifier</strong> for six types of binary shapes: Alien, Arrow, Butterfly, Face, Star and Toonhead. It follows the object’s boundary, turns that into numerical features and predicts the class.","A chain code records movement along the edge between black and white regions. A Fourier transform converts that boundary into frequency components. Keeping only the lower frequencies lets the classifier focus on the overall shape instead of small details or artefacts.","Training calculates a mean, covariance and prior probability for each class from labelled images. A new image’s features are scored against those Gaussian models, and the highest-scoring class is the prediction.","Testing checks predictions against the classes in the image filenames and records a <strong>confusion matrix</strong>. That shows which shapes it gets right and which ones it mixes up.","The recovered project has 222 training images, 221 test images, saved model workspaces and the original report. The repository is private."],"media":[{"type":"image","src":"projects/image-classifier/images/image-classifier-screenshot-01.png","alt":"","poster":""},{"type":"image","src":"projects/image-classifier/images/image-classifier-screenshot-02.png","alt":"","poster":""}],"smart":["The images have no holes or separate internal boundaries, because the chain-code implementation follows one boundary.","A Fourier transform converts the boundary movements into frequencies. Lower frequencies keep the overall shape and leave out finer details.","Of the feature counts I tested, the first <strong>six Fourier features</strong> worked best on this image set.","Training saves each class’s mean and covariance in a <code>.mat</code> file. The proportion of training images in each class gives its prior probability.","The score uses the class likelihood and prior in Bayes’ rule. It leaves out <code>p(x)</code> because that term is the same for every class being compared.","The probability calculation uses logarithms to reduce rounding problems with very small values.","A normalised confusion matrix shows mistakes by actual and predicted class.","<code>train(N)</code> builds the models with N Fourier features. <code>classify(imagepath)</code> loads the saved workspace and returns the highest-scoring class.","<code>testMultipleFrequencies.m</code> tries feature counts from 2 to 30, retraining and testing each time.","The code still has its original local paths. The repository README explains what to change before running training and evaluation."],"links":[]},{"id":"new-5a52dd88","name":"New project","repoUrl":"","tagline":"","how":[],"media":[],"smart":[],"links":[]},{"id":"penguin-steps","name":"Penguin Steps","repoUrl":"","tagline":"Compare daily steps with a partner using Apple Health. Each of you has a penguin that moves as you walk, so you can see who’s ahead.","how":["Penguin Steps lets you <strong>compare daily steps with a partner</strong>. Pair up in the iOS app and each of you gets a penguin that moves as you walk.","Apple Health supplies the recorded step counts, so you can see who’s ahead without sending each other totals manually."],"media":[{"type":"image","src":"projects/penguin-steps/images/penguin-steps-main-screen.jpg","alt":"Penguin Steps main screen","poster":""},{"type":"image","src":"projects/penguin-steps/images/penguin-steps-screen-02.jpg","alt":"Penguin Steps second screen","poster":""}],"smart":["<strong>Shared trail language:</strong> JavaScript generates the SVG path data for the web interface, while <code>JavaScriptCore</code> runs the same generator for the SwiftUI widget. The graphic has one source of truth and can be reproduced consistently on another platform.","A custom <strong>Capacitor bridge</strong> connects the web interface to native health, pairing and widget services","<strong>Reactive message bus:</strong> A message bus allows for better interaction between the <code>Svelte</code> UI and iOS, making the user interface reactive and completely independent from the app's HealthKit, background delivery, persistence, widgets and bundle management logic.","<strong>Zipped web releases:</strong> The remote web build is packaged as a zip, downloaded by the native app and stored locally as an installable bundle.","<strong>Offline-safe:</strong> The app can keep using the offline and locally stored bundle after installation, while still checking for a newer version in the background.","<strong>Shared widget state:</strong> Shared App Group storage lets the app and widget read the same step counts, penguin selections and update timestamps.","<strong>No App Store bottleneck:</strong> The GitHub workflow can build and publish a new UI bundle without requiring a new native binary for every interface change. UI fixes and visual refinements can reach the app without waiting for another App Store review, while platform-level changes still belong in the native release.","<strong>Lightweight pairing:</strong> Firebase handles anonymous identity, partner pairing and live step updates without requiring a traditional account-creation flow."],"links":[["App Store","https://apps.apple.com/gb/app/penguin-steps/id6762652426"]]},{"id":"dropleet","name":"Dropleet","repoUrl":"","tagline":"LeetCode problems broken into smaller questions, so you can work through the reasoning behind a solution. An LLM generates question sets from JSON you supply, and Google Forms collects the answers. The site is static, so you can share it without needing an account or running a backend.","how":["Dropleet splits <strong>Java interview problems</strong> into smaller questions, so you can practise the decisions that lead to a solution.","An LLM generates the question sets from JSON you supply. The result is a static website you can share with someone else.","Google Forms collects the answers, so the site doesn’t need its own application backend and you don’t need a Dropleet account."],"media":[{"type":"image","src":"projects/dropleet/images/dropleet-main-screen.jpg","alt":"Dropleet main screen","poster":""},{"type":"image","src":"projects/dropleet/images/dropleet-screen-02.png","alt":"Dropleet second screen","poster":""},{"type":"image","src":"projects/dropleet/images/dropleet-screen-03.png","alt":"Dropleet third screen","poster":""}],"smart":["<b>Crowdsourced, on-demand lessons</b>: Lessons are structured JSON and rendered through one shared interface, so a generated walkthrough can become a self-test for anyone working through the same problem. New lessons are created only when requested, avoiding both one-off screens and a library of unused generated content.","<strong>Learn by trying:</strong> Test an idea in a small prompt, get a hint if needed, then see the explanation. That creates a more active first encounter with a difficult problem than jumping straight to a full solution after a failed attempt.","<strong>Leave and resume seamlessly:</strong> Hard problems are broken into smaller decisions, and progress is saved in the browser. You can leave at any point and return to the same step, hints and draft later.","<strong>Serverless sharing:</strong> Google Forms and Google Sheets provide a lightweight, serverless shared backend for contributed lessons, without introducing a conventional application server.","<strong>Linking Leetcode:</strong> The original problem, explanations and study links remain available alongside the interactive layer, so the generated lesson adds a guided route through the material rather than replacing the source content."],"links":[["Visit site","https://dropleet.co.uk/"]]},{"id":"pixelbot","name":"Pixelbot","repoUrl":"","tagline":"If you’re waiting for something on your Mac, pick a pixel that will change when it’s done. Pixelbot watches it and notifies your phone, so you don’t have to keep checking the screen.","how":["Pixelbot watches a <strong>pixel on your Mac</strong> and notifies your phone if it changes. If a queue moving or a download finishing changes something on screen, that can be enough to tell you it’s done.","Pixelbot Dashboard on the Mac watches the selected pixel, and Pixelbot on iOS receives the notification. That way you can leave the computer instead of checking it repeatedly.","You don’t need an account. Both apps are available through their respective App Stores."],"media":[{"type":"video","src":"projects/pixelbot/videos/pixelbot-demo.mp4","alt":"Pixelbot demo","poster":""},{"type":"image","src":"projects/pixelbot/images/pixelbot-iphone-screen.jpg","alt":"Pixelbot iPhone app","poster":""},{"type":"image","src":"projects/pixelbot/images/pixelbot-mac-dashboard.jpg","alt":"Pixelbot Mac dashboard","poster":""}],"smart":[],"links":[["App Store","https://apps.apple.com/gb/app/pixelbot/id1560553386"],["Mac App Store","https://apps.apple.com/gb/app/pixelbot-dashboard/id1560523831?mt=12"]]},{"id":"cell","name":"Cell Counter","repoUrl":"","tagline":"Count cells from a photo of a microscope screen, then calculate seeding density, well counts and media volumes in the same tool. You don’t need an account.","how":["Cell Counter uses image processing to estimate how many cells are visible in a <strong>photo of a microscope screen</strong>.","It also calculates seeding density, well counts and media volumes, so you can use the same tool for counting and preparation.","It runs in the browser without an account. The screenshots show the counter and the other calculators."],"media":[{"type":"image","src":"projects/cell/images/cell-screen-01.png","alt":"Cell Counter main screen","poster":""},{"type":"image","src":"projects/cell/images/cell-screen-02.png","alt":"Cell Counter second screen","poster":""},{"type":"image","src":"projects/cell/images/cell-screen-03.png","alt":"Cell Counter third screen","poster":""},{"type":"image","src":"projects/cell/images/cell-screen-04.png","alt":"Cell Counter fourth screen","poster":""}],"smart":[],"links":[["Visit site","https://scout-38aa2.web.app/cell"]]},{"id":"family","name":"Family Tree","repoUrl":"","tagline":"A family tree you can explore as a graph and edit as text. You can import or export the tree, and you don’t need an account.","how":["Family Tree combines an <strong>interactive graph</strong> with a text editor, so you can follow relationships visually and edit the tree.","You can import and export the text to move a tree into the editor or keep a copy of the data.","It runs in the browser and you don’t need an account."],"media":[{"type":"image","src":"projects/family/images/family-main-screen.png","alt":"Family Tree main screen","poster":""},{"type":"image","src":"projects/family/images/family-screen-02.png","alt":"Family Tree second screen","poster":""}],"smart":[],"links":[["Visit site","https://scout-38aa2.web.app/family/"]]},{"id":"map","name":"Map","repoUrl":"","tagline":"A map experiment where you can save routes, time journeys and compare your position with a virtual pace setter.","how":["Sometimes Google Maps cannot tell you if you're able to make an appointment \\"if you walk a little faster\\".","I just wanted a real-time update on whether I am behind or ahead of schedule when getting somewhere.","This app aims to allow you to relax while trying to get somewhere."],"media":[],"smart":["Uses Leaflet as the core map library and OpenStreetMap for map tiles.","Built with SvelteKit, TypeScript and Vite.","<strong>Route creation:</strong> Routes can be drawn on the map, extracted from an uploaded image using OpenCV, or loaded from previously saved paths.","Routes can be moved and resized before starting a journey.","Saved routes and journey history are stored locally on the device using localStorage.","<strong>GPS matching:</strong> Matches GPS positions to progress along the route, taking previous movement into account to handle loops, crossings and backtracking.","<strong>GPS filtering:</strong> Filters out inaccurate readings and implausible jumps to keep progress estimates more stable.","<strong>Live arrival estimates:</strong> Estimates your pace from recent movement along the route and updates your predicted arrival time.","<strong>Schedule tracking:</strong> Shows whether you're on time or running late, alongside the pace needed to reach your destination by the chosen time.","Displays a virtual pacer that follows the route toward your target arrival time.","<strong>Historical pacing:</strong> Uses previous journeys to adjust the pacer's speed across different sections of the route, accounting for places where you usually slow down or stop.","Records journey progress locally and can resume recently unfinished journeys.","<strong>Route suggestions:</strong> Suggests saved routes based on your current location and previous departure times.","<strong>Minimal map view:</strong> Keeps speed, predicted arrival and recording status visible while walking, with other controls hidden.","Receives location updates from a native wrapper through window events.","Includes automated tests for route processing, GPS matching and historical pace calculations."],"links":[["Visit site","https://scout-38aa2.web.app/map"]]},{"id":"block-cipher-aes-128-apps","name":"Block Cipher AES-128 apps","repoUrl":"https://github.com/yissok/your-encrypter","tagline":"System shortcuts for encrypting and decrypting text on your device using AES-128.","how":["A Swift project that connects <strong>AES-128 text encryption and decryption</strong> to system shortcuts.","The actions run on your device. You can use them through shortcuts without a separate hosted service."],"media":[],"smart":[],"links":[]},{"id":"picture-encrypter","name":"Picture encrypter","repoUrl":"https://github.com/yissok/encrypture","tagline":"Encrypts pictures with AES-128, turning them into images that look like static.","how":["Picture encrypter uses <strong>AES-128 to encrypt pictures</strong>, producing images that look like static.","I used Swift, image processing and encryption to try this with picture data. The repository is private."],"media":[],"smart":[],"links":[]},{"id":"kubernetes-full-stack","name":"Kubernetes full-stack","repoUrl":"https://github.com/yissok/kube","tagline":"A template for running a Java backend and React frontend with Kubernetes. You access the app through the server IP.","how":["A template for running a <strong>React frontend and Java backend</strong> with Kubernetes.","You access it through the server IP. It gives you a starting point for trying a deployment with both the browser interface and backend service."],"media":[],"smart":[],"links":[]},{"id":"cost-saving-personal-backend","name":"Cost-saving personal backend","repoUrl":"https://github.com/yissok/backend","tagline":"A personal backend using API Gateway, MongoDB and Node.js authentication on EC2, with CloudFront serving the static frontend. CloudFormation and GitHub Actions handle the infrastructure and deployment.","how":["An AWS experiment for a <strong>personal application backend</strong>. It uses API Gateway, a Java backend, MongoDB storage and a Node.js authentication service on EC2.","CloudFront serves the static frontend separately, so the website and backend can be managed independently.","CloudFormation defines the infrastructure and GitHub Actions handles builds and deployment. The code is split across backend, static-frontend and node-bastion repositories."],"media":[],"smart":[],"links":[["Static frontend","https://github.com/yissok/static-frontend"],["Node bastion","https://github.com/yissok/node-bastion"]]},{"id":"zero-operating-cost-contractor-site-tap-in","name":"Zero operating cost Contractor site tap in","repoUrl":"https://github.com/yissok/site","tagline":"A contractor tap-in site that uses Google Sheets as its database and a static interface, with no operating cost.","how":["A contractor tap-in site with a static interface and <strong>Google Sheets as the database</strong>.","Google Apps Script connects the two, so the site uses existing services without needing a dedicated application server."],"media":[],"smart":[],"links":[]},{"id":"coffee-chatbot","name":"Coffee chatbot","repoUrl":"","tagline":"A bot for coordinating coffee deliveries through Symphony chat. I built it, but it’s no longer hosted and the source isn’t available here.","how":["A Python chatbot for <strong>coordinating coffee deliveries</strong> through Symphony chat.","The bot handled coffee requests in chat and helped organise deliveries. I built it, but it’s no longer hosted.","It was built at a Nomura hackathon, where the project came <strong>first out of 10 teams</strong>."],"media":[],"smart":[],"links":[],"availability":"We built this at a Nomura hackathon on company laptops, so the source isn’t available here. The bot isn’t hosted publicly either, but this page explains what it did."},{"id":"knowledge-share-chatbot","name":"Knowledge-share chatbot","repoUrl":"https://github.com/yissok/nomuraLifehacks","tagline":"A chatbot that passes questions to people who might know the answer.","how":["A chatbot that <strong>passes questions to people who might know the answer</strong>, so knowledge in a group is easier to find.","It uses Node.js and MySQL. The repository is private."],"media":[],"smart":[],"links":[]}]`),C={version:k,site:A,featuredProjects:S,archiveProjects:T,work:j,projectDetails:P};export{C as c,I as i};
